import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import org.json.*;
public final class BackupZip{
 private BackupZip(){} private static final long LIMIT=250L*1024*1024;
 public static byte[] create(String json,String version)throws Exception{JSONObject root=new JSONObject(json);JSONArray cases=root.optJSONArray("cases");if(cases==null)cases=new JSONArray();JSONObject m=new JSONObject().put("backupFormat","personal-growth-backup").put("backupVersion",2).put("appVersion",version).put("exportedAt",root.optString("exportedAt","")).put("caseCount",cases.length()).put("primaryData","data.json").put("reportFile","report.xlsx").put("restoreRule","JSON_PRIMARY_EXCEL_FULL_REPORT");ByteArrayOutputStream out=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out,StandardCharsets.UTF_8)){put(z,"manifest.json",m.toString(2).getBytes(StandardCharsets.UTF_8));put(z,"data.json",root.toString(2).getBytes(StandardCharsets.UTF_8));put(z,"report.xlsx",xlsx(cases));}return out.toByteArray();}
 public static String extractDataJson(byte[] bytes)throws Exception{String data=null;boolean manifest=false,excel=false;long total=0;Set<String> names=new HashSet<>();try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(bytes),StandardCharsets.UTF_8)){ZipEntry e;while((e=z.getNextEntry())!=null){String n=e.getName().replace('\\','/');if(n.startsWith("/")||n.contains("../")||!names.add(n))throw new Exception("Cấu trúc ZIP không an toàn");if(e.isDirectory())continue;byte[] b=read(z,80L*1024*1024);total+=b.length;if(total>LIMIT)throw new Exception("Gói sao lưu quá lớn");if(n.equals("manifest.json")){JSONObject m=new JSONObject(new String(b,StandardCharsets.UTF_8));if(!"personal-growth-backup".equals(m.optString("backupFormat")))throw new Exception("Không đúng gói Personal Growth");manifest=true;}else if(n.equals("data.json"))data=new String(b,StandardCharsets.UTF_8);else if(n.equals("report.xlsx")){if(b.length<4||b[0]!='P'||b[1]!='K')throw new Exception("report.xlsx không hợp lệ");excel=true;}}}if(!manifest||data==null||!excel)throw new Exception("ZIP phải có manifest.json, data.json và report.xlsx");JSONObject root=new JSONObject(data);if(root.optJSONArray("cases")==null)throw new Exception("data.json thiếu danh sách hồ sơ");return root.toString();}
 private static byte[] read(InputStream in,long limit)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))>0){if(o.size()+n>limit)throw new Exception("Tệp trong ZIP quá lớn");o.write(b,0,n);}return o.toByteArray();}private static void put(ZipOutputStream z,String n,byte[] b)throws Exception{z.putNextEntry(new ZipEntry(n));z.write(b);z.closeEntry();}
 private static byte[] xlsx(JSONArray cases)throws Exception{List<Sheet>s=new ArrayList<>();Sheet full=new Sheet("Full Records",new String[]{"Case ID","Tiêu đề","Loại","Nhóm","Mức độ","Ảnh hưởng ban đầu","Mức trực quan","Trạng thái","Bắt đầu","Tạo lúc","Cập nhật lúc","Đóng lúc","Người liên quan","Địa điểm","Mô tả","Ảnh JSON","Cập nhật JSON","Phương án JSON","Kết quả cuối JSON","Toàn bộ hồ sơ JSON"});Sheet updates=new Sheet("Updates",new String[]{"Case ID","STT","Loại","Nội dung","Thời gian","Phút","Chi phí","Toàn bộ cập nhật JSON"});Sheet sols=new Sheet("Solutions",new String[]{"Case ID","STT","Tên","Mô tả","Ngày bắt đầu","Ngày đánh giá","Tiêu chí thành công","Toàn bộ phương án JSON"});Sheet photos=new Sheet("Photos",new String[]{"Case ID","STT","Dữ liệu hoặc đường dẫn ảnh"});Sheet fin=new Sheet("Final Results",new String[]{"Case ID","Kết quả thực tế","Điểm tốt","Điểm cần thay đổi","Bài học","Đánh giá","Hiệu quả","Quyết định","Ngày đóng","Toàn bộ kết quả JSON"});for(int i=0;i<cases.length();i++){JSONObject c=cases.optJSONObject(i);if(c==null)continue;String id=c.optString("id","");JSONArray u=c.optJSONArray("updates"),q=c.optJSONArray("solutions"),p=c.optJSONArray("photos"),im=c.optJSONArray("impacts");JSONObject f=c.optJSONObject("final");full.add(id,c.optString("title"),c.optString("type"),c.optString("category"),String.valueOf(c.optInt("severity",0)),im==null?"[]":im.toString(),c.optString("visualSeverity"),c.optString("status"),c.optString("startedAt"),c.optString("createdAt"),c.optString("updatedAt"),c.optString("closedAt"),c.optString("owner"),c.optString("location"),c.optString("description"),p==null?"[]":p.toString(),u==null?"[]":u.toString(),q==null?"[]":q.toString(),f==null?"":f.toString(),c.toString());if(u!=null)for(int j=0;j<u.length();j++){JSONObject x=u.optJSONObject(j);if(x!=null)updates.add(id,""+(j+1),x.optString("type"),first(x,"content","text","description"),first(x,"at","timestamp","createdAt","date"),""+x.optInt("minutes",x.optInt("duration",0)),""+x.optDouble("cost",0),x.toString());}if(q!=null)for(int j=0;j<q.length();j++){JSONObject x=q.optJSONObject(j);if(x!=null)sols.add(id,""+(j+1),first(x,"name","title"),first(x,"description","content"),first(x,"startDate","startedAt"),first(x,"reviewDate","evaluationDate"),first(x,"successCriteria","criteria"),x.toString());}if(p!=null)for(int j=0;j<p.length();j++)photos.add(id,""+(j+1),p.optString(j,""));if(f!=null)fin.add(id,first(f,"result","actualResult"),first(f,"good","strengths"),first(f,"bad","improvements"),first(f,"lesson","lessons"),first(f,"evaluation","assessment"),""+f.optInt("effectiveness",0),first(f,"decision","finalDecision"),c.optString("closedAt"),f.toString());}s.add(full);s.add(updates);s.add(sols);s.add(fin);s.add(photos);return write(s);}
 private static String first(JSONObject o,String...k){for(String x:k){String v=o.optString(x,"");if(!v.isEmpty())return v;}return "";}
 private static byte[] write(List<Sheet>s)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(o,StandardCharsets.UTF_8)){text(z,"[Content_Types].xml",types(s.size()));text(z,"_rels/.rels","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");text(z,"xl/workbook.xml",book(s));text(z,"xl/_rels/workbook.xml.rels",rels(s.size()));text(z,"xl/styles.xml",styles());for(int i=0;i<s.size();i++)text(z,"xl/worksheets/sheet"+(i+1)+".xml",sheet(s.get(i)));}return o.toByteArray();}private static void text(ZipOutputStream z,String n,String x)throws Exception{put(z,n,x.getBytes(StandardCharsets.UTF_8));}
 private static String types(int n){StringBuilder b=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>");for(int i=1;i<=n;i++)b.append("<Override PartName=\"/xl/worksheets/sheet").append(i).append(".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");return b.append("</Types>").toString();}private static String book(List<Sheet>s){StringBuilder b=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>");for(int i=0;i<s.size();i++)b.append("<sheet name=\"").append(esc(s.get(i).name)).append("\" sheetId=\"").append(i+1).append("\" r:id=\"rId").append(i+1).append("\"/>");return b.append("</sheets></workbook>").toString();}private static String rels(int n){StringBuilder b=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">");for(int i=1;i<=n;i++)b.append("<Relationship Id=\"rId").append(i).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet").append(i).append(".xml\"/>");return b.append("<Relationship Id=\"rId").append(n+1).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>").toString();}private static String styles(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"2\"><font><sz val=\"10\"/></font><font><b/><color rgb=\"FFFFFFFF\"/><sz val=\"10\"/></font></fonts><fills count=\"3\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF1477EA\"/></patternFill></fill></fills><borders count=\"1\"><border/></borders><cellStyleXfs count=\"1\"><xf/></cellStyleXfs><cellXfs count=\"2\"><xf/><xf fontId=\"1\" fillId=\"2\" applyFont=\"1\" applyFill=\"1\"/></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>";}private static String sheet(Sheet s){int cols=s.rows.get(0).length;StringBuilder b=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" state=\"frozen\"/></sheetView></sheetViews><cols>");for(int i=1;i<=cols;i++)b.append("<col min=\"").append(i).append("\" max=\"").append(i).append("\" width=\"").append(i>15?45:22).append("\" customWidth=\"1\"/>");b.append("</cols><sheetData>");for(int r=0;r<s.rows.size();r++){b.append("<row r=\"").append(r+1).append("\">");String[] x=s.rows.get(r);for(int c=0;c<x.length;c++)b.append("<c r=\"").append(col(c+1)).append(r+1).append("\" t=\"inlineStr\"").append(r==0?" s=\"1\"":"").append("><is><t xml:space=\"preserve\">").append(esc(x[c])).append("</t></is></c>");b.append("</row>");}return b.append("</sheetData><autoFilter ref=\"A1:").append(col(cols)).append(s.rows.size()).append("\"/></worksheet>").toString();}private static String col(int n){StringBuilder b=new StringBuilder();while(n>0){n--;b.insert(0,(char)('A'+n%26));n/=26;}return b.toString();}private static String esc(String x){if(x==null)return"";return x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}private static final class Sheet{String name;List<String[]>rows=new ArrayList<>();Sheet(String n,String[]h){name=n;rows.add(h);}void add(String...x){rows.add(x);}}
}
